// 紙鶴的線索與揭曉（按寄信人）
const ARC_LINES = {
  TRIP_WALK:{"pei": "……還不錯。比試煉場好看一點。@shy", "qin": "我是這次的領隊助教。……不過今天，就當我是來玩的。三年前你剛入學，走山路還跌跌撞撞的。@smile", "tang": "哇——！好漂亮好漂亮！我要摘一朵帶回去給我娘！@laugh", "jiang": "白天的山谷，和星圖上畫的一樣。……不，比星圖好看。@smile", "lu": "這片山谷，校史裡記載過。可是書上的字，寫不出這個顏色。@surprise", "wen": "今天的運勢是大大大吉！因為風景這麼好！@laugh", "lin": "這裡的藥草好多……啊，對不起，我又看草看到忘了你。@shy", "ye": "山路滑。手給我。……這是醫師的職責。@shy", "ruan": "小白！小白你看！有好多花靈！@laugh", "su": "這片花海，不是幻術。……真的東西，有時候比幻術還漂亮。@smile", "liu": "風吹過花海的聲音……我想把它寫進下一首曲子。@smile", "ji": "我帶了畫具。可是……我不想畫了。我想用眼睛記住。@shy", "bai": "二十年前，我也帶學生來過這裡。……這一次，是你帶我來的。@sad"},
  TRIP_FIRE:{"pei": "三年前，我只想贏。現在……我只想大家都在。@shy", "qin": "你知道嗎？三年前，我最怕的就是又有人消失。……現在，我不怕了。@smile", "tang": "畢業以後……我還可以去找你嗎？騎馬也好，走路也好，我一定會去！@sad", "jiang": "我算過畢業以後的日子。……可是那裡面，我最想算準的，只有你。@shy", "lu": "這三年，我會寫進校史裡。最長的一章，是你。@shy", "wen": "我好怕畢業喔……可是想到你，就沒那麼怕了。@sad", "lin": "這三年，被你照顧的時候，比我照顧你的時候還多。@shy", "ye": "……三年。好快。我不擅長說這種話。總之，謝謝你。@shy", "ruan": "我、我剛入學的時候，什麼都不敢說。現在，我敢說了：我最喜歡你了！@shy", "su": "三年前，我不知道什麼是真的。現在我知道了。……你就是。@shy", "liu": "這三年，像一首很長的曲子。我希望，它永遠不要彈完。@sad", "ji": "我畫了你三年。可是今晚的你，我不想畫。我想就這樣看著。@shy", "bai": "謝謝你。是你讓我，又可以坐在營火邊，和大家一起。@smile"},
  LAST:{"pei": "寫點什麼。……隨便什麼都好。只是……別寫「保重」。我不喜歡那兩個字。@shy", "qin": "助教也可以有紀念冊吧？我去年那本，最後一頁一直空著。……給你寫。@smile", "tang": "你要寫滿一整頁喔！我會每天看的！@laugh", "jiang": "我在紀念冊上，畫了你的星軌。……你也幫我寫一句。@shy", "lu": "這是我的紀念冊。……第一個請你寫。註腳也可以。@shy", "wen": "寫一個願望給我！我會幫你保管十年！不，一輩子！@laugh", "lin": "寫什麼都好。我只是……想留下你的字。@shy", "ye": "我的紀念冊，去年就寫滿了。只留了最後一頁，沒給任何人寫。……不准寫醫囑。@shy", "ruan": "小白說，要你寫在最前面！……其實是我想要的。@shy", "su": "寫一句真話給我。……就一句。@calm", "liu": "這是我的譜本。最後一頁，留給你寫。@shy", "ji": "我的畫冊最後一頁。……你說過，要留給我們的。@shy", "bai": "老師也想要一頁。……二十年前那本，沒能寫完。@sad"},
  CRANE_HINT:{pei:'「畫得不好看。是玫瑰。不准笑。」',qin:'「一朵玫瑰。下面寫著：規矩之外的話，只說給你聽。」',tang:'「一朵畫得歪歪的桂花，旁邊寫著：猜到了也不准說！」',jiang:'「一朵鳶尾，花心點著七顆小小的星。」',lu:'「一朵鳶尾，旁邊用很小的字標著：註一。」',wen:'「一朵鳶尾，旁邊寫著：今天的運勢是——猜猜看！」',lin:'「一朵鈴蘭，旁邊夾著一片薄荷葉。」',ye:'「一朵鈴蘭，下面寫著：早點睡。」',ruan:'「一朵鈴蘭，旁邊畫了一隻歪歪的白色小狐狸。」',su:'「一朵紫藤。可是你一眨眼，它就變成了一朵小小的木蘭。」',liu:'「一朵紫藤，旁邊畫了三個音符。」',ji:'「一朵紫藤，畫得非常、非常好看。」'},
  CRANE_REVEAL:{pei:'……看什麼。對，是我。字太醜了，你笑吧。@shy',qin:'……我不擅長說話。所以寫了下來。@shy',tang:'被你發現了！嗚哇，好丟臉！可是……都是真心話喔！@shy',jiang:'我算過，用紙鶴說話，被拒絕的機率最小。……結果你找到我了。@shy',lu:'……我以為，用寫的比較不會說錯話。@shy',wen:'嘿嘿……是我！占卜說，要先用紙鶴，再用當面！@laugh',lin:'……那些話，我想了很久，還是覺得寫下來比較好。@shy',ye:'……是我。別告訴別人。@shy',ruan:'是、是我……小白幫我折的！不對，是我自己折的！@shy',su:'這次沒有幻術。紙鶴是真的，話也是真的。@shy',liu:'有些話說不出口，就寫在紙上。……就像寫曲子一樣。@shy',ji:'我本來想畫一幅畫送你。可是，有些話畫不出來。@shy'},
  TOURN_YES:{pei:'……行。我們一組，就只有贏這一條路。@laugh',qin:'好。我會把你的背後，守得好好的。@calm',tang:'太好了！我們一定會贏的！我的火已經燒起來了！@laugh',jiang:'我算過了。和你一組，勝率最高。……也最開心。@shy',lu:'……我不擅長實戰。不過，我會幫你算好每一步。@shy',wen:'好耶！我已經占過了，我們是大吉組合！@laugh',lin:'我會在你旁邊，幫你療傷。……你不會受傷的。@smile',ye:'可以。受傷的話，我就在旁邊。@calm',ruan:'我、我嗎？……好！小白也會加油的！@surprise',su:'有意思。我們就讓全場看看，什麼是真的、什麼是假的。@laugh',liu:'……好。我的琴聲，會跟著你的節奏。@smile',ji:'好啊。我會一邊打，一邊把你畫進去。@laugh',bai:'……我已經很久沒有站上試煉場了。好，我陪你。@smile'},
  TOURN_PREP:{pei:'再快一點！……不對，你剛剛那一下很好。再來一次。@calm',qin:'步法對了。手放鬆。記住這個感覺。@calm',tang:'我們來練習默契！我出火，你接！……啊，燒到你了嗎？對不起！@shy',jiang:'對手的出招順序，我已經推算出來了。你只要記住三個字：等、看、打。@calm',lu:'我把歷屆大會的戰術整理成一頁。……你先背起來。@calm',wen:'我幫你占了！明天的幸運招式是……全部！@laugh',lin:'累了就休息一下。我帶了薄荷茶。@smile',ye:'手腕繃太緊了。……放鬆。對，就是這樣。@calm',ruan:'我、我會努力不拖累你的！@shy',su:'別讓對手看穿你下一步。……連我也別讓我看穿。@laugh',liu:'跟著節拍。一、二、三——好。@smile',ji:'你出手的那一瞬間，很好看。再來一次，我想記住。@shy',bai:'溯光的要訣，是看見本來的樣子。對手也是。@calm'},
  TOURN_WIN:{pei:'……贏了。是我們贏了。你剛剛那一下，我會記一輩子。@laugh',qin:'做得好。……你站在台上的樣子，很好看。@smile',tang:'贏了贏了贏了！我要寫信告訴我娘！@laugh',jiang:'和我推算的一樣。……不，比我推算的還要好。@laugh',lu:'這一場，我會寫進校史裡。……私人註腳也算。@shy',wen:'我就說是大吉吧！我們是最強的！@laugh',lin:'你沒有受傷吧？……太好了。我們贏了。@laugh',ye:'沒有人受傷。很好。……還有，我們贏了。@smile',ruan:'我、我們贏了？真的嗎？小白！我們贏了！@laugh',su:'看吧，全場都看見了。這一次，是真的。@laugh',liu:'剛才那一刻，像一首曲子的最後一個音。很完美。@laugh',ji:'我要把剛剛那一幕畫下來。你一定要當模特兒。@laugh',bai:'……謝謝你，讓我又站上了這裡。@smile'},
  TOURN_LOSE:{pei:'……輸了。下次，我們一定贏。說好了。@angry',qin:'輸了也沒關係。你沒有受傷，這最重要。@calm',tang:'嗚……輸了。可是跟你一組，好開心。@sad',jiang:'是我推算錯了一步。……對不起。@sad',lu:'失敗也是史料。我們把它記下來，明年再來。@calm',wen:'嗚哇，占卜不準……可是我還是很開心！@sad',lin:'沒關係。你受傷的地方，我幫你擦藥。@smile',ye:'輸了。可是你一直到最後都沒有放棄。……很好。@calm',ruan:'對、對不起……是我太慢了……@sad',su:'輸了。……不過，我剛才是真的很開心。@smile',liu:'差一個音。下一次，我們會彈完它。@sad',ji:'沒關係。輸掉的那一場，我也想畫下來。@smile',bai:'輸了也很好。你今天，很耀眼。@smile'},
};
return {ARCS,ARC_LINES,VARY2,FACE_TAGS,TUT,VARY,END,BOND,YEAR,POST,QUESTS4,CH4,TIPS,CH3,BAIC,EV_BAI,LIFE2,GOODS,SORT,QUESTS2,CH2,LIFE,MAGIC,TEA,HOUSES,STATS,STAT_ORDER,C,BAI,GRAN,FACES,EV,QUESTS,MAIN,PROLOGUE,PLACES,LOOK,FREE,CLASS_TEXT,SCENE_IMG,SCENE_FALLBACK,CG};
